urlset:
{% for asset in media %}

        {% if asset.media_type == 'video' %}
            {{ url_for('media.video.single', id=asset.id, _external=True) }}
        {% elif asset.media_type == 'audio' %}
            {{ url_for('media.audio.single', id=asset.id, _external=True) }}
        {% elif asset.media_type == 'code' %}
            https://media.themetacity.com{{ url_for('media.show_specific_code', code_id=asset.id) }}
        {% elif asset.media_type == 'gallery' %}
            https://media.themetacity.com{{ url_for('media.show_specific_picture', picture_id=asset.id) }}
        {% endif %}
        {{ asset.date_published.strftime('%Y-%m-%d') }}
        never

{% endfor %}
